  );
}

function getLinkErrorStatus(error: LinkOrderToShipmentError): number {
  switch (error.code) {
    case "shipment_not_found":
    case "order_not_found":
      return 404;
    case "order_already_linked":
    case "shipment_not_linkable":
      return 409;
